<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useApi} from '../composables/useApi'
const {apiFetch}=useApi();const state=ref<any>(null),channel=ref('stable'),error=ref(''),message=ref(''),busy=ref(false)
onMounted(async()=>{try{state.value=await apiFetch('/api/self-update/channel');channel.value=state.value.channel}catch(e:any){error.value=e.message}})
async function save(){busy.value=true;error.value='';try{state.value=await apiFetch('/api/self-update/channel',{method:'PUT',body:JSON.stringify({channel:channel.value})});message.value='Channel saved. Check images to review the candidate before installing.'}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="cyber-card space-y-3"><h2 class="font-semibold">Update channel</h2><p class="text-sm text-muted">Stable follows reviewed releases; beta follows prereleases; edge follows validated main builds. Changing channels does not install an update.</p><div class="flex gap-2"><select v-model="channel" class="cyber-input"><option value="stable">Stable</option><option value="beta">Beta</option><option value="edge">Edge</option></select><button class="cyber-btn-secondary" :disabled="busy || !state" @click="save">Save channel</button></div><p v-if="state" class="text-xs break-all">Candidate source: {{state.image}}. {{state.signed_updates?'Official registry digests must pass publisher signature verification.':'Custom/local images use operator-managed trust.'}}</p><p v-if="state?.override" class="text-xs text-amber-800">The installation sets an explicit update image. That setting takes priority over this channel.</p><p v-if="error" role="alert" class="text-red-700">{{error}}</p><p v-if="message" role="status" class="text-emerald-700">{{message}}</p></section></template>
